use chrono::{Duration, Utc};
use pyloros::code_exchange::{Exchange, ExchangeRequest, Refusal, redeem};
use sqlx::PgPool;
use uuid::Uuid;

// Generated by the reference Argon2id client-secret hasher from synthetic inputs.
const CURRENT: &str = "$argon2id$v=19$m=65536,t=3,p=4$jNH6XwvB+F8rJSSklBJCKA$oqK3cymfWAvf2VdVy1kHyMY37eyi7e5vkDc0Oo3IKYY";
const OLD: &str = "$argon2id$v=19$m=65536,t=3,p=4$JSQk5DyH0BpjjJGyljLGWA$RiKiVcamaZDbHogGuPeq11AdpkEEJ9MknMCYqbeu54c";

#[tokio::test]
#[ignore = "requires PostgreSQL; run just test-db"]
async fn client_credentials_are_checked_before_the_grant() {
    let pool = PgPool::connect(&std::env::var("DATABASE_URL").unwrap())
        .await
        .unwrap();
    let mut tx = pool.begin().await.unwrap();
    sqlx::query(
        "CREATE TEMP TABLE oauth_clients(client_id text, client_type text,
        grant_types text, active boolean, secret_hash text, previous_secret_hash text,
        previous_secret_expires_at timestamptz)",
    )
    .execute(&mut *tx)
    .await
    .unwrap();
    let deadline = Utc::now();
    sqlx::query(
        "INSERT INTO oauth_clients VALUES
        ('web','confidential','refresh_token authorization_code',true,$1,$2,$3),
        ('inactive','public','authorization_code',false,'',NULL,NULL),
        ('browser','public','authorization_code',true,'',NULL,NULL),
        ('service','confidential','client_credentials',true,$1,NULL,NULL)",
    )
    .bind(CURRENT)
    .bind(OLD)
    .bind(deadline)
    .execute(&mut *tx)
    .await
    .unwrap();
    let before = deadline - Duration::seconds(1);
    for (client, secret, time, expected) in [
        ("web", Some("test-current"), deadline, Refusal::MissingCode),
        ("web", Some("test-old"), before, Refusal::MissingCode),
        ("web", Some("test-old"), deadline, Refusal::BadClientSecret),
        (
            "web",
            Some("test-old"),
            deadline + Duration::seconds(1),
            Refusal::BadClientSecret,
        ),
        ("web", None, before, Refusal::BadClientSecret),
        ("web", Some("incorrect"), before, Refusal::BadClientSecret),
        ("inactive", None, before, Refusal::UnknownClient),
        ("absent", None, before, Refusal::UnknownClient),
        ("", None, before, Refusal::MissingClient),
        ("browser", None, before, Refusal::MissingCode),
        (
            "service",
            Some("test-current"),
            before,
            Refusal::UnauthorizedClient,
        ),
        (
            "service",
            Some("incorrect"),
            before,
            Refusal::BadClientSecret,
        ),
    ] {
        let req = ExchangeRequest {
            client_id: client,
            client_secret: secret,
            code: "",
            verifier: "",
            redirect_uri: None,
            resources: &[],
        };
        let Exchange::Refused(reason) = redeem(&mut tx, &req, Uuid::new_v4(), time).await.unwrap()
        else {
            panic!("grant accepted")
        };
        assert_eq!(reason, expected);
    }
    tx.rollback().await.unwrap();
}
